            connected: true,
            unit: 'C',                // 'C', 'F', 'K'
            precision: 2,             // 0, 1, 2, 3 decimal places
            offset: 0.0,              // ±5.0 °C offset calibration
            samplingInterval: 1000,   // ms
            highThreshold: 32.0,      // °C
            lowThreshold: 15.0,       // °C
            baseAmbient: 24.15,       // °C initial base temperature
            noiseDrift: 0.0,

            // LED State
            led: {
